<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\Helpdesk as H; use Moves\Services\HelpdeskNotifier; use Moves\Support\CmsView as V;
$t = H::ticket($id); if ($t === null) { http_response_code(404); echo V::empty('Chamado não encontrado.'); return; }
HelpdeskNotifier::markTicketRead((int) $admin['id'], 'staff', $id);
$reply = CmsAuth::can($admin, 'tickets.reply'); $assign = CmsAuth::can($admin, 'tickets.assign');
$agents = ['' => 'Sem responsável']; foreach (H::agents() as $a) { $agents[$a['user_id']] = trim($a['first_name'] . ' ' . $a['last_name']); }
$eventLabel = ['created' => 'Chamado aberto', 'status' => 'Situação', 'reopened' => 'Reaberto', 'priority' => 'Prioridade', 'assigned' => 'Atribuído', 'transferred' => 'Transferido', 'unassigned' => 'Atribuição removida'];
$valueLabel = static fn (?string $v): string => $v === null ? '—' : (V::TICKET_STATUS[$v] ?? V::PRIORITIES[$v] ?? $v); ?>
<div class="cms-grid-2"><div>
<div class="cms-card"><h2><?= V::e($t['protocol']) ?> · <?= V::e($t['subject']) ?></h2><div class="cms-timeline"><?php foreach (H::timeline($id, true) as $item): ?>
<?php if ($item['kind'] === 'event'): ?><div class="cms-event"><?= V::date($item['created_at']) ?> · <?= V::e($eventLabel[$item['event_type']] ?? $item['event_type']) ?><?= $item['to_value'] && $item['event_type'] !== 'created' ? ': ' . V::e($valueLabel($item['from_value'])) . ' → ' . V::e($valueLabel($item['to_value'])) : '' ?> · <?= V::e($item['actor_name'] ?? 'Sistema') ?></div>
<?php else: ?><article class="cms-msg <?= $item['visibility'] === 'internal' ? 'cms-msg-internal' : ($item['author_type'] === 'staff' ? 'cms-msg-staff' : '') ?>"><header><strong><?= V::e($item['author_name'] ?? '') ?><?= $item['visibility'] === 'internal' ? ' · Nota interna' : '' ?></strong><span><?= V::date($item['created_at']) ?></span></header><p><?= V::e($item['body']) ?></p><?php if ($item['attachments']): ?><div class="cms-attachments"><?php foreach ($item['attachments'] as $file): ?><a href="/chamados/anexo/<?= (int) $file['id'] ?>"><?= V::e($file['original_name']) ?> (<?= V::size((int) $file['size_bytes']) ?>)</a><?php if ($assign): ?><?= V::actionButton('ticket-attachment-delete', 'Remover', ['id' => $file['id']], 'cms-btn-danger', 'Remover este anexo?') ?><?php endif; ?><?php endforeach; ?></div><?php endif; ?></article><?php endif; ?>
<?php endforeach; ?></div></div>
<?php if ($reply): ?><form class="cms-card" method="post" action="/acao/ticket-reply" enctype="multipart/form-data"><h2>Responder</h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Mensagem', 'body', '', ['type' => 'textarea', 'rows' => 5, 'required' => true]) ?><div class="cms-field"><label for="ticket-files">Anexos (imagem, PDF ou texto, até 10 MB)</label><input id="ticket-files" type="file" name="attachments[]" multiple accept=".jpg,.jpeg,.png,.gif,.webp,.pdf,.txt"></div><?= V::field('Nota interna: o cliente não vê', 'internal', '0', ['type' => 'checkbox']) ?><button class="cms-btn-primary">Enviar</button></form><?php endif; ?></div>
<aside><div class="cms-card"><h2>Detalhes</h2><dl class="cms-dl"><dt>Situação</dt><dd><?= V::badge($t['status'], V::TICKET_STATUS[$t['status']] ?? $t['status']) ?></dd><dt>Prioridade</dt><dd><?= V::badge($t['priority'], V::PRIORITIES[$t['priority']] ?? $t['priority']) ?> <small>Sugerida: <?= V::e(V::PRIORITIES[$t['suggested_priority']] ?? '') ?></small></dd><dt>Cliente</dt><dd><?= V::e($t['requester_name']) ?><br><small><?= V::e($t['requester_email']) ?></small></dd><dt>Contexto</dt><dd><?= V::e($t['organization_name'] ?? 'Pessoal') ?></dd><dt>Categoria</dt><dd><?= V::e($t['category_name']) ?></dd><dt>Tipo</dt><dd><?= $t['support_type'] === 'billing' ? 'Financeiro' : 'Técnico' ?><?= $t['module_hint'] !== '' ? ' · ' . V::e($t['module_hint']) : '' ?></dd><dt>Responsável</dt><dd><?= V::e($t['assignee_name'] ?? '—') ?></dd><dt>Abertura</dt><dd><?= V::date($t['created_at']) ?></dd><dt>Primeira resposta</dt><dd><?= V::date($t['first_response_at']) ?><?= $t['first_response_due_at'] ? ' <small>Meta: ' . V::date($t['first_response_due_at']) . '</small>' : '' ?></dd><dt>Resolução</dt><dd><?= V::date($t['resolved_at']) ?><?= $t['resolution_due_at'] ? ' <small>Meta: ' . V::date($t['resolution_due_at']) . '</small>' : '' ?></dd><dt>Reaberturas</dt><dd><?= (int) $t['reopened_count'] ?></dd><?php if ($t['rating']): ?><dt>Avaliação</dt><dd><?= V::badge($t['rating'], V::RATINGS[$t['rating']] ?? $t['rating']) ?> <?= V::e($t['rating_comment']) ?></dd><?php endif; ?></dl></div>
<?php if ($reply && H::allowedStatuses($t['status'])): $options = []; foreach (H::allowedStatuses($t['status']) as $s) { $options[$s] = V::TICKET_STATUS[$s]; } ?><form class="cms-card" method="post" action="/acao/ticket-status"><h2>Alterar situação</h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Nova situação', 'status', '', ['type' => 'select', 'choices' => $options]) ?><button class="cms-btn">Alterar</button></form><?php endif; ?>
<?php if ($assign): ?><form class="cms-card" method="post" action="/acao/ticket-assign"><h2>Responsável</h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Atribuir ou transferir para', 'assignee_user_id', $t['assignee_user_id'] ?? '', ['type' => 'select', 'choices' => $agents]) ?><button class="cms-btn">Salvar</button></form>
<form class="cms-card" method="post" action="/acao/ticket-priority"><h2>Prioridade</h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Prioridade revisada', 'priority', $t['priority'], ['type' => 'select', 'choices' => V::PRIORITIES]) ?><button class="cms-btn">Salvar</button></form><?php endif; ?></aside></div>
